// Pick the image file for the current month, time of day and weather.
// File name: <Month>.<TimeOfDay>.<Weather>.<Ratio>.png
// Example:   September.Morning.Clear.169.png
// Output 1: msg.filename is set. Output 2: 404 reply (no image).

// ---- Settings -----------------------------------------------------------
const IMAGE_DIR = '/data/';            // Folder with the image files
const TIME_ZONE = 'America/Chicago';   // Your time zone (IANA name)
const EVENING_MINUTES = 90;            // Evening starts this many minutes before sunset

// Home Assistant weather state -> weather names in the file names.
// The flow uses the first name that has a file. The other names are similar weather.
const WEATHER_NAMES = {
    'sunny':           ['Clear', 'PartlyCloudy'],
    'clear-night':     ['Clear', 'PartlyCloudy'],
    'partlycloudy':    ['PartlyCloudy', 'Clear', 'Cloudy'],
    'cloudy':          ['Cloudy', 'PartlyCloudy'],
    'fog':             ['Fog', 'Cloudy'],
    'rainy':           ['Rainy', 'Pouring', 'Cloudy'],
    'pouring':         ['Pouring', 'Rainy', 'Cloudy'],
    'lightning':       ['Lightning', 'LightningRainy', 'Rainy', 'Cloudy'],
    'lightning-rainy': ['LightningRainy', 'Lightning', 'Pouring', 'Rainy', 'Cloudy'],
    'hail':            ['Hail', 'Pouring', 'Rainy', 'Cloudy'],
    'snowy':           ['Snowy', 'SnowyRainy', 'Cloudy'],
    'snowy-rainy':     ['SnowyRainy', 'Snowy', 'Rainy', 'Cloudy'],
    'windy':           ['Windy', 'PartlyCloudy', 'Clear'],
    'windy-variant':   ['Windy', 'Cloudy', 'PartlyCloudy'],
    'exceptional':     ['Exceptional', 'Cloudy'],
};
// Used when the weather state is not in the table (for example "unavailable").
const UNKNOWN_WEATHER_NAMES = ['PartlyCloudy', 'Clear', 'Cloudy'];
// --------------------------------------------------------------------------

const ratio = String((msg.req && msg.req.params && msg.req.params.ratio) || '');
if (!/^\d+$/.test(ratio)) {
    node.status({ fill: 'red', shape: 'ring', text: `Bad ratio: ${ratio}` });
    return notFound(`Unknown aspect ratio "${ratio}". Use /weather169 or /weather916.`);
}

const now = new Date();
const month = new Intl.DateTimeFormat('en-US', { timeZone: TIME_ZONE, month: 'long' }).format(now);
const timeOfDay = sunTimeOfDay(msg.sun, now) || clockTimeOfDay(now);
const weather = String(msg.weather || '').toLowerCase();
const knownWeather = Object.prototype.hasOwnProperty.call(WEATHER_NAMES, weather);
const weatherNames = knownWeather ? WEATHER_NAMES[weather] : UNKNOWN_WEATHER_NAMES;

const tried = [];
for (const name of weatherNames) {
    const file = `${month}.${timeOfDay}.${name}.${ratio}.png`;
    tried.push(file);
    if (fs.existsSync(IMAGE_DIR + file)) {
        msg.filename = IMAGE_DIR + file;
        node.status(knownWeather
            ? { fill: 'green', shape: 'dot', text: file }
            : { fill: 'yellow', shape: 'dot', text: `${file} (weather: ${weather || 'none'})` });
        return [msg, null];
    }
}

node.status({ fill: 'red', shape: 'ring', text: `No image: ${tried[0]}` });
return notFound(`No image for weather "${weather}". Tried: ${tried.join(', ')}`);

// Send a 404 text reply on output 2.
function notFound(text) {
    msg.statusCode = 404;
    msg.headers = { 'content-type': 'text/plain; charset=utf-8' };
    msg.payload = text;
    return [null, msg];
}

// Time of day from the Home Assistant sun.sun entity. Returns null if the data is not usable.
//   Morning:   dawn to halfway between sunrise and solar noon
//   Afternoon: halfway between sunrise and solar noon, to EVENING_MINUTES before sunset
//   Evening:   EVENING_MINUTES before sunset to dusk
//   Night:     dusk to dawn
function sunTimeOfDay(sun, now) {
    const a = (sun && sun.attributes) || {};
    const dawn = Date.parse(a.next_dawn);
    const dusk = Date.parse(a.next_dusk);
    const noon = Date.parse(a.next_noon);
    const setting = Date.parse(a.next_setting);
    let rising = Date.parse(a.next_rising);
    if ([dawn, dusk, noon, setting, rising].some(Number.isNaN)) {
        return null;
    }
    if (dawn < dusk) return 'Night';        // Dusk is past. Dawn is next.
    if (setting > dusk) return 'Evening';   // Sunset is past. Dusk is next.
    if (noon < setting) {                   // Solar noon is next.
        if (rising > noon) rising -= 24 * 3600 * 1000;   // Sunrise is past. Use the sunrise of today.
        return now.getTime() < (rising + noon) / 2 ? 'Morning' : 'Afternoon';
    }
    if (setting - now.getTime() <= EVENING_MINUTES * 60 * 1000) return 'Evening';
    return 'Afternoon';
}

// Time of day from the clock. Used only when the sun data is not available.
function clockTimeOfDay(now) {
    const hour = Number(new Intl.DateTimeFormat('en-US', { timeZone: TIME_ZONE, hour: 'numeric', hourCycle: 'h23' }).format(now)) % 24;
    if (hour >= 5 && hour < 12) return 'Morning';
    if (hour >= 12 && hour < 17) return 'Afternoon';
    if (hour >= 17 && hour < 21) return 'Evening';
    return 'Night';
}
